		/**
		 * Returns a new populated Brand
		 * 
		 * @return Brand
		 */
		protected Brand generateNewEntity() {
			Brand entity = new Brand( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  new HashSet<>() );
			
			return( entity );
		}

